    size_t obj_size;
    int ret;

    if (!vgdev || !bo_ptr) {
        return -EINVAL;
    }

    /* Determine the object type based on the kernel flag */
    if (kernel) {
        /* Kernel objects require additional alignment */
        obj_size = sizeof(struct virtio_gpu_object) + size;
    } else {
        obj_size = sizeof(struct virtio_gpu_object);
    }

    /* Allocate memory for the GPU object */
    bo = calloc(1, obj_size);
    if (!bo) {
        return -ENOMEM;
    }

    /* Initialize the GPU object */
    bo->size = size;
    bo->kernel = kernel;
    bo->pinned = pinned;

    /* Set up placement based on pinned flag */
