int virtio_gpu_object_create(struct virtio_gpu_device *vgdev, unsigned long size,
                             bool kernel, bool pinned, struct virtio_gpu_object **bo_ptr)
{
    struct virtio_gpu_object *bo;
    int ret = -ENOMEM;

    bo = kzalloc(sizeof(*bo), GFP_KERNEL);
    if (!bo)
        return -ENOMEM;

    if (kernel) {
        bo->type = VIRTIO_GPU_OBJECT_KERNEL;
    } else {
        bo->type = VIRTIO_GPU_OBJECT_USER;
    }

    bo->size = size;
    bo->kernel = kernel;
    bo->pinned = pinned;

    ret = virtio_gpu_mem_alloc(vgdev, size, &bo->dma_addr, &bo->vaddr, kernel, pinned);
    if (ret) {
        goto free_bo;
    }

    *bo_ptr = bo;
    return 0;

free_bo:
    kfree(bo);
    return ret;
}
